<?php get_header(); ?><main id="primary" class="content-area"><div class="container"><header class="section-heading"><div class="section-kicker">Ntamba Journal</div><h1><?php the_archive_title(); ?></h1></header><div class="journal-grid"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="product-card"><div class="product-thumb"><?php ntamba_thumbnail('medium_large'); ?></div><div class="product-body"><div class="product-meta"><?php ntamba_posted_on(); ?></div><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),20)); ?></p></div></article><?php endwhile;else: ?><div class="notice">No stories found.</div><?php endif; ?></div><?php the_posts_pagination(); ?></div></main><?php get_footer(); ?>